import { test } from 'node:test';
import assert from 'node:assert/strict';
import { payable } from './discount.mjs';
test('20% off', () => assert.equal(payable(1000, 20), 800));
test('round cents', () => assert.equal(payable(999, 15), 849));
test('zero', () => assert.equal(payable(0, 20), 0));

